mapper.update:
update oa_attendance_leave_type
set status = #{status}, row_version = row_version + 1,
    update_by = #{updateBy}, update_time = now()
where leave_type_id = #{leaveTypeId}
  and row_version = #{rowVersion}

update oa_attendance_leave_request
set leave_type_id = #{leaveTypeId}, start_time = #{startTime},
    end_time = #{endTime}, total_minutes = #{totalMinutes}, requested_days=#{requestedDays}, quota_policy_json=#{quotaPolicyJson}, quota_units=#{quotaUnits}, quota_status=#{quotaStatus},
    reason = #{reason}, row_version = row_version + 1,
    update_by = #{updateBy}, update_time = now()
where leave_request_id = #{leaveRequestId}
  and user_id = #{userId} and shop_id = #{shopId}
  and status in ('DRAFT', 'RETURNED')
  and row_version = #{rowVersion}

