order by r.start_time desc, r.leave_request_id desc


where r.shop_id = #{shopId}
and r.user_id = #{userId}
and r.status = #{status}
and r.end_time >= #{dateFrom}
and r.start_time < date_add(#{dateTo}, interval 1 day)
order by r.start_time desc, r.leave_request_id desc

select count(*)
from oa_attendance_leave_request
where user_id = #{userId}
  and leave_request_id != coalesce(#{excludeId}, -1)
  and status in ('DRAFT', 'SUBMITTING', 'PENDING', 'APPROVED', 'RETURNED')
  and start_time < #{endTime} and end_time > #{startTime}

select count(*)
from oa_attendance_schedule s
where s.user_id = #{userId} and s.shop_id = #{shopId}
  and s.status in ('PUBLISHED', 'CHANGED')
  and timestamp(s.business_date, s.start_time_snapshot) < #{endTime}
  and timestamp(
        case when s.cross_day_snapshot = 1
                   or s.end_time_snapshot <= s.start_time_snapshot
             then date_add(s.business_date, interval 1 day)
             else s.business_date end,
        s.end_time_snapshot) > #{startTime}

select 
from oa_attendance_leave_attachment
where attachment_id = #{attachmentId}

mapper.delete:
delete from oa_attendance_leave_attachment
where attachment_id = #{attachmentId}
  and leave_request_id = #{leaveRequestId}

mapper.update:
update oa_attendance_leave_request
set status = 'APPROVED', approved_at = now(), submitted_at = now(),
    row_version = row_version + 1, update_by = #{updateBy},
    update_time = now()
where leave_request_id = #{leaveRequestId}
  and status = #{expectedStatus} and row_version = #{expectedVersion}

update oa_attendance_leave_request
set status = 'PENDING', approval_instance_id = #{instanceId},
    row_version = row_version + 1, update_by = #{updateBy},
    update_time = now()
where leave_request_id = #{leaveRequestId}
  and status = 'SUBMITTING'
  and business_round = #{businessRound}
  and row_version = #{expectedVersion}
  and approval_instance_id is null

update oa_attendance_leave_request
set status = 'CANCELLED', cancelled_at = now(), remark = #{reason},
    row_version = row_version + 1, update_by = #{updateBy},
    update_time = now()
where leave_request_id = #{leaveRequestId}
  and status = #{expectedStatus} and row_version = #{expectedVersion}

