limit 1

mapper.update:
update oa_attendance_leave_approval_start_outbox
set status = 'PROCESSING', attempt_count = attempt_count + 1,
    next_retry_at = null, claim_token = #{claimToken},
    claimed_at = now(), row_version = row_version + 1,
    update_time = now()
where outbox_id = #{outboxId}
  and status = #{expectedStatus}
  and row_version = #{expectedVersion}

update oa_attendance_leave_approval_start_outbox
set status = 'RETRY', next_retry_at = #{nextRetryAt},
    last_http_status = #{lastHttpStatus},
    last_error_code = #{lastErrorCode}, last_error = #{lastError},
    claim_token = null, claimed_at = null,
    row_version = row_version + 1, update_time = now()
where outbox_id = #{outboxId}
  and status = #{expectedStatus}
  and row_version = #{expectedVersion}

update oa_attendance_leave_approval_start_outbox
set status = 'FAILED', next_retry_at = null,
    last_http_status = #{lastHttpStatus},
    last_error_code = #{lastErrorCode}, last_error = #{lastError},
    claim_token = null, claimed_at = null,
    row_version = row_version + 1, update_time = now()
where outbox_id = #{outboxId}
  and status = #{expectedStatus}
  and row_version = #{expectedVersion}

update oa_attendance_leave_approval_start_outbox
set status = 'COMPLETED', completed_at = now(), next_retry_at = null,
    last_error_code = null, last_error = null,
    claim_token = null, claimed_at = null,
    row_version = row_version + 1, update_time = now()
where outbox_id = #{outboxId}
  and status = #{expectedStatus}
  and row_version = #{expectedVersion}
